args.old_str:
unsigned codepoint;
 p = utf8_to_codepoint(p, &codepoint);
 glyphSet_t *set = R_GetGlyphSet(font, codepoint);
 stbtt_bakedchar *g = &set->glyphs[codepoint & 0xff];
 FLOAT charWidth = INV_SCALE_X(g->xadvance);
 if (arg->wordWrap && ((cursor.x + charWidth) - (pos.x + arg->textWidth))> 0.001) {
     cursor.x = pos.x;
     cursor.y += linesize * arg->lineHeight;
 }
 if (draw) {
     FLOAT const w = set->image->width;
     FLOAT const h = set->image->height;
     RECT const uv_rect = get_uvrect(g, h, w);
     RECT const screen = get_screenrect(&cursor, g);
     R_DrawImage2(set->image, &screen, &uv_rect, color,arg->model_matrix);
 }
 cursor.x += charWidth;

args.new_str:
unsigned codepoint;
 p = utf8_to_codepoint(p, &codepoint);

 // 传入 draw 参数，表示是否需要纹理
 glyphSet_t *set = R_GetGlyphSet(font, codepoint, draw);

 // 安全地获取 glyph
 stbtt_bakedchar *g = &set->glyphs[codepoint & 0xff];

 // 确保 glyph 数据有效
 if (g->x1 <= g->x0) {
     // 字符加载失败，使用默认宽度
     FLOAT charWidth = INV_SCALE_X(font->size * 0.5); // 默认宽度
     cursor.x += charWidth;
     continue;
 }

 FLOAT charWidth = INV_SCALE_X(g->xadvance);
 if (arg->wordWrap && ((cursor.x + charWidth) - (pos.x + arg->textWidth))> 0.001) {
     cursor.x = pos.x;
     cursor.y += linesize * arg->lineHeight;
 }
 if (draw) {
     // 安全访问纹理尺寸
     FLOAT w, h;
     if (set->image) {
         w = (FLOAT)set->image->width;
         h = (FLOAT)set->image->height;
     } else {
         w = h = 1.0f; // 使用安全值
     }

     // 避免除零错误
     if (w <= 0.0f) w = 1.0f;
     if (h <= 0.0f) h = 1.0f;

     RECT const uv_rect = get_uvrect(g, h, w);
     RECT const screen = get_screenrect(&cursor, g);
     R_DrawImage2(set->image, &screen, &uv_rect, color,arg->model_matrix);
 }
 cursor.x += charWidth;
